/**
 * Reads test/fixtures/premise*.arrow — the same three values (0.05, -12.34, 0)
 * written at every bitWidth Arrow defines for Decimal — with apache-arrow's
 * own accessors, then with this library's. Fixtures are generated by pyarrow
 * (test/fixtures/generate_fixtures.py).
 *
 *   node examples/compare.ts
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { tableFromIPC } from 'apache-arrow';
import { toDecimalString } from '../src/index.ts';

const fixturesDir = path.join(path.dirname(fileURLToPath(import.meta.url)), '../test/fixtures');

function show(file: string) {
  const table = tableFromIPC(fs.readFileSync(path.join(fixturesDir, file)));
  const vector = table.getChild('value')!;
  console.log(`\n  decimal${vector.type.bitWidth}(precision=${vector.type.precision}, scale=${vector.type.scale})\n`);
  for (let i = 0; i < vector.length; i++) {
    const value = vector.get(i)!;
    let raw: string;
    try {
      raw = String(value);
    } catch (err) {
      raw = `throws: ${(err as Error).message}`;
    }
    let rawNumber: string;
    try {
      rawNumber = String(Number(value));
    } catch (err) {
      rawNumber = `throws: ${(err as Error).message}`;
    }
    const fixed = toDecimalString(value, vector.type);
    console.log(`    String()=${raw.padEnd(28)} Number()=${rawNumber.padEnd(34)} toDecimalString=${fixed}`);
  }
}

for (const file of ['premise32.arrow', 'premise64.arrow', 'premise.arrow', 'premise256.arrow']) {
  show(file);
}
console.log();
